  name_zh: clearWinner ? top.name_zh : null,
  confidence: clearWinner ? 0.9 : 0,
  clarification_required: !clearWinner,
  candidates: scored.slice(0, 3).map(r => ({ taxonomy_id: r.taxonomy_id, name_en: r.name_en, name_zh: r.name_zh }))
});

