const raw = $input.first().json;
const ctx = $('Normalize and screen input').first().json;
const zh  = ctx.language === 'zh';

// FIX P3: table content is echoed into drafts. Strip control characters and
// collapse whitespace so an instruction injected into a service name cannot
// restructure the draft that a staff member reads.
function safe(v, max) {
  return String(v ?? '').replace(/[�-]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max || 200);
}
function money(v) { const n = Number(v); return Number.isFinite(n) ? n.toFixed(2) : '?'; }

let p = raw.output;
try { if (typeof p === 'string') p = JSON.parse(p); } catch { p = null; }

const errors = [];
const notConfigured = [];
const toolFailures = [];
const toolCalls = [];
const evidence = { services: [], promotions: [], stylists: [], styles: [] };
const steps = raw.intermediateSteps ?? [];

for (const st of steps) {
  if (st && st.action && st.action.tool) toolCalls.push(st.action.tool);
  let o = st ? st.observation : null;
  try {
    for (let d = 0; d < 6; d++) {
      if (typeof o === 'string') { o = JSON.parse(o); continue; }
      if (Array.isArray(o)) { o = o[0]; continue; }
      if (o && o.json) { o = o.json; continue; }
      if (o && o.response) { o = o.response; continue; }
      break;
    }
    if (!o) continue;
    if (o.ok !== true) {
      if (o.error === 'not_configured') notConfigured.push(o.tool);
      else if (['confirmation_required', 'human_required', 'invalid_input'].indexOf(o.error) === -1) toolFailures.push(o.tool + ':' + String(o.error ?? 'unknown'));
      continue;
    }
    if (o.tool === 'service_catalog') evidence.services.push(...(o.services ?? []));
    if (o.tool === 'get_promotions') { evidence.promotions.push(...(o.promotions ?? [])); if (o.resolved_service) evidence.services.push(o.resolved_service); }
    if (o.tool === 'match_stylist') { evidence.stylists.push(...(o.stylists ?? [])); if (o.resolved_style) evidence.styles.push(o.resolved_style); }
    if (o.tool === 'classify_style' && o.confidence >= 0.8 && o.taxonomy_id) {
      evidence.styles.push({ taxonomy_id: o.taxonomy_id, name_en: o.name_en, name_zh: o.name_zh });
    }
  } catch (e) { /* unparseable observation contributes no evidence */ }
}

// repeated identical tool calls must not duplicate draft lines
const uniq = (arr, key) => { const seen = new Set(); return arr.filter(r => { const k = r && r[key]; if (seen.has(k)) return false; seen.add(k); return true; }); };
evidence.services   = uniq(evidence.services, 'service_id');
evidence.promotions = uniq(evidence.promotions, 'promotion_id');
evidence.stylists   = uniq(evidence.stylists, 'stylist_id');
evidence.styles     = uniq(evidence.styles, 'taxonomy_id');

if (!p || typeof p !== 'object') errors.push('invalid_agent_output');
p = p ?? {};

for (const pair of [
  ['service_ids', 'services', 'service_id'],
  ['promotion_ids', 'promotions', 'promotion_id'],
  ['stylist_ids', 'stylists', 'stylist_id']
]) {
  const field = pair[0], key = pair[1], idKey = pair[2];
  if (!Array.isArray(p[field])) { errors.push('invalid_' + field); continue; }
  for (const v of p[field]) if (!evidence[key].some(r => r[idKey] === v)) errors.push('unsupported_' + field);
}
if (p.taxonomy_id && !evidence.styles.some(r => r.taxonomy_id === p.taxonomy_id)) errors.push('unsupported_taxonomy');

const requiredTool = { catalog: 'service_catalog', promotions: 'get_promotions', style: 'classify_style', stylist: 'match_stylist' }[p.intent];
if (requiredTool && toolCalls.indexOf(requiredTool) === -1) errors.push('required_tool_not_called');
if (raw.error) errors.push('agent_failed');

let reason = p.escalate === true ? 'agent_escalation' : (errors.length ? 'guardrail_blocked' : 'shadow_review');
if (toolFailures.length && reason === 'shadow_review') reason = 'tool_failure';
const escalate = p.escalate === true || errors.length > 0 || toolFailures.length > 0;

// A not_configured backend is a known limitation of this draft, not a fault. The
// fact that such a tool was called is the structural signal - it does not depend
// on whatever intent/escalate flag the model happened to choose. Staff see the
// precise limitation instead of a generic "needs review"; nothing claims success.
// Only take over the draft when the model itself framed the turn as booking /
// profile (or escalated). Live run: on "I want a long bob" the model over-called
// the profile tools; a stylist answer must not be hijacked by that detour.
// Live run 3: on "Is the EOFY sale still on?" the model wandered into booking
// stubs and escalated; taking over the draft with booking text was wrong. Only
// the model's own booking/profile intent may trigger the override.
const hitBooking = errors.length === 0 && toolFailures.length === 0 && p.intent === 'booking';
const hitProfile = errors.length === 0 && toolFailures.length === 0 && p.intent === 'profile';
// Live run 3: after get_promotions came back empty for "Is the EOFY sale still
// on?", the model tried every other tool and escalated. Its evidence-backed
// answer ("no verified promotions") is still the right draft; the escalation is
// kept in `reason` for staff. The generic text is reserved for a guardrail
// error, a real tool failure, or an escalation with no substantive intent.
const substantive = ['catalog', 'promotions', 'style', 'stylist'].indexOf(p.intent) !== -1;
const escalateGeneric = errors.length > 0 || toolFailures.length > 0 || (p.escalate === true && !substantive && !hitBooking && !hitProfile);

// Evidence-backed prices are rendered whenever the model referenced a service,
// whatever intent it picked. Live run: "How much is a men's cut?" came back as
// intent=promotions with service_ids=[svc_cut_men]; the price must still show.
const priceRows = evidence.services.filter(r => (Array.isArray(p.service_ids) ? p.service_ids : []).indexOf(r.service_id) !== -1);
const priceLines = priceRows.map(r => safe(zh ? (r.name_zh || r.name) : r.name) + ' - ' + safe(r.currency, 8) + ' ' + money(r.price) + ' / ' + Number(r.duration_min) + (zh ? ' 分钟' : ' minutes')).join('\n');
const styleRow = p.taxonomy_id ? evidence.styles.find(r => r.taxonomy_id === p.taxonomy_id) : null;
const styleLine = styleRow
  ? (zh ? '匹配的发型：' : 'Matched hairstyle: ') + safe(zh ? styleRow.name_zh : styleRow.name_en) + ' [' + safe(styleRow.taxonomy_id, 60) + ']' + (zh ? '。请确认这是否是您想要的发型。' : '. Please confirm this is the style you mean.')
  : '';
let generic = false;

let reply = '';
if (hitBooking) {
  reply = zh
    ? '预约系统与身份验证尚未连接。未创建、修改或取消任何预约，请由店员协助。'
    : 'The booking system and identity verification are not connected. No appointment was created, changed or cancelled; a salon staff member must assist.';
  reason = 'booking_setup_required';
} else if (hitProfile) {
  reply = zh
    ? '请自报发丝形态、密度、孔隙度以及染烫漂历史。不确定的项目可留空；确认资料与保存授权后才能建档。目前未保存资料。'
    : 'Please self-report your texture, density, porosity and colour/perm/bleach history. Unknown fields can stay blank. Confirmation and storage consent are required before saving; no profile has been saved.';
  reason = 'profile_setup_required';
} else if (escalateGeneric) {
  reply = zh ? '此请求需要店员人工复核。' : 'This request needs a salon staff member to review it.';
  generic = true;
} else if (p.intent === 'catalog') {
  reply = priceLines || (zh ? '尚无已核实的服务价格，请让店员提供价目表。' : 'No verified service prices are configured yet. Please ask the salon for its price list.');
} else if (p.intent === 'promotions') {
  const rows = evidence.promotions.filter(r => (p.promotion_ids ?? []).indexOf(r.promotion_id) !== -1);
  reply = rows.length
    ? rows.map(r => safe(r.title) + ' [' + safe(r.promotion_id, 60) + ']').join('\n')
    : (zh ? '当前没有可核实且适用的促销。' : 'There are currently no verified eligible promotions.');
} else if (p.intent === 'style') {
  reply = styleLine || (zh ? '请描述长度、层次及刘海，帮助确认发型。' : 'Please describe the length, layers and fringe so we can clarify the style.');
} else if (p.intent === 'stylist') {
  const rows = evidence.stylists.filter(r => (p.stylist_ids ?? []).indexOf(r.stylist_id) !== -1);
  const labels = {
    style_specialty: zh ? '发型专长' : 'style specialty',
    texture_experience: zh ? '自报发质经验' : 'experience with your self-reported texture',
    language_match: zh ? '语言匹配' : 'language match'
  };
  reply = rows.length
    ? rows.map(r => safe(r.name, 80) + ' - ' + (r.reasons ?? []).map(k => labels[k] || k).join(', ')).join('\n') +
      (zh ? '\n档期尚未核实。' : '\nAvailability has not been verified.')
    : (zh ? '没有符合条件的发型师。可以放宽语言或价位条件后再查。' : 'No matching stylists are configured. You can relax language or price-tier preferences and try again.');
} else {
  const qs = {
    service: zh ? '您想了解哪项服务？' : 'Which service are you interested in?',
    style: zh ? '您想要什么发型或长度？' : 'What hairstyle or length would you like?',
    texture: zh ? '您自报的发丝形态是什么？' : 'How would you describe your hair texture?',
    language: zh ? '您偏好哪种沟通语言？' : 'Which language do you prefer?',
    budget: zh ? '您偏好的价位是多少？' : 'What price tier do you prefer?',
    profile_consent: zh ? '是否同意在核实身份并确认资料后保存发质档案？' : 'Would you consent to saving a hair profile after identity verification and confirmation?',
    none: zh ? '您好，我可以协助了解服务、促销和发型。本对话为内部人工复核草稿。' : 'Hello! I can help with services, promotions and hairstyles. This is an internal draft for staff review.'
  };
  reply = qs[p.question] ?? qs.none;
}

if (!generic && p.intent !== 'style' && styleLine) reply = styleLine + '\n' + reply;
if (!generic && p.intent !== 'catalog' && priceLines) reply = priceLines + '\n' + reply;

if (ctx.truncated) reply += zh ? '\n（注意：用户输入过长已被截断，请复核原文。）' : '\n(Note: the user message was truncated; please check the original.)';

const hallucinationBlocked = errors.filter(e => e.indexOf('unsupported_') === 0).length;

return [{ json: {
  session_id: ctx.sessionId,
  request_text: ctx.chatInput,
  draft_reply: reply,
  reason,
  status: 'pending',
  guardrail_pass: errors.length === 0,
  errors,
  requires_human: true,
  tool_calls: toolCalls,
  not_configured_tools: notConfigured,
  truncated: !!ctx.truncated,
  // Ready-made numeric metrics: drop an Evaluation node (Set Metrics) after this
  // node and map these straight through. See PLAN.md Phase 6.
  metrics: {
    guardrail_pass: errors.length === 0 ? 1 : 0,
    errors_count: errors.length,
    hallucination_blocked: hallucinationBlocked,
    tool_call_count: toolCalls.length,
    escalated: escalate ? 1 : 0,
    agent_failed: raw.error ? 1 : 0,
    tool_failures: toolFailures.length,
    not_configured_hit: notConfigured.length ? 1 : 0
  },
  output: (zh ? '[人工复核草稿]\n' : '[DRAFT FOR STAFF REVIEW]\n') + reply
} }];

const draft   = $('Draft ready').first().json;
const written = $input.first().json;
const zh = /[㐀-鿿]/.test(String(draft.request_text ?? ''));
const queued = !!(written && !written.error && written.id);
const tail = queued
  ? (zh ? '\n\n复核队列条目：' : '\n\nReview queue entry: ') + written.id
  : (zh ? '\n\n[警告] 写入复核队列失败，本草稿未被记录，请人工留存。'
        : '\n\n[WARNING] The review queue write failed - this draft was NOT recorded. Please capture it manually.');
return [{ json: {
  output: String(draft.output ?? '') + tail,
  queued,
  queue_id: queued ? written.id : null,
  metrics: draft.metrics,
  reason: draft.reason,
  guardrail_pass: draft.guardrail_pass
} }];
